try {
  const alert = new AlertNotification({
    // Don't add an icon on macOS, the app icon is already shown.
    imageURL:
      AppConstants.platform == "macosx"
        ? ""
        : "chrome://branding/content/icon48.png",
    title: this.brandShortName,
    text: formattedString,
    textClickable: canMakeException,
    cookie,
    requireInteraction: true,
  });
  this.alertService.showAlertWithCallbacks(alert, {
    QueryInterface: ChromeUtils.generateQI(["nsIAlertCallbacks"]),
    onAlertClick(_action) {
      showExceptionDialog();
    },
    onAlertFinished() {
      deferred.resolve();
    },
  });
